"""Map pixel positions from the original video into shot-tracker coordinates.

WHY THE CHECK STILL FAILS
-------------------------
The expected output for the frame center (960, 540) depends on the tracker's
crop rectangle, and that rectangle isn't in the plan or in anything I've been
shown. I won't hard-code made-up crop numbers, because a guess that happens to
pass a check would still give wrong positions on real footage.

This version tries to find the real crop on its own. It looks next to this
file and in the current directory for:
  * a JSON config with crop keys (crop_x/crop_y/crop_width/crop_height,
    "crop": [x, y, w, h], or "crop": {"x", "y", "width", "height"}), or
  * the tracker's Python source with a literal crop such as
    `frame[180:900, 320:1600]`, plus an optional `cv2.resize(..., (w, h))`.
If it finds exactly one candidate, it uses it. If it finds none or several,
it raises an error that lists what it found.

If auto-discovery doesn't work for your setup, fill in CROP below. You can
also pass the values as arguments, put them in tracker_config.json, or set the
TRACKER_* environment variables. If you send me the tracker's crop/resize
code, I'll confirm the correct value for (960, 540).

Mapping:
    tracker = (original - crop_origin) * (tracker_size / crop_size)
"""

import json
import os
import re

# ---------------------------------------------------------------------------
# FILL THESE IN with your tracker's real values (they take top priority).
# Example: CROP = {"crop_x": 320, "crop_y": 180, "crop_width": 1280,
#                  "crop_height": 720, "tracker_width": 640,
#                  "tracker_height": 360}
# tracker_width/height can be left out if the crop isn't resized.
# ---------------------------------------------------------------------------
CROP = None

# "pixels"     -> pixel coordinates in the tracker's input image (default)
# "normalized" -> 0..1 relative to the tracker image
# "centered"   -> pixels relative to the tracker image center
OUTPUT_MODE = os.environ.get("TRACKER_OUTPUT_MODE", "pixels")

_HERE = os.path.dirname(os.path.abspath(__file__))
_CONFIG_FILE = os.path.join(_HERE, "tracker_config.json")
_KEYS = ("crop_x", "crop_y", "crop_width", "crop_height",
         "tracker_width", "tracker_height")
_ENV = {
    "crop_x": "TRACKER_CROP_X",
    "crop_y": "TRACKER_CROP_Y",
    "crop_width": "TRACKER_CROP_WIDTH",
    "crop_height": "TRACKER_CROP_HEIGHT",
    "tracker_width": "TRACKER_WIDTH",
    "tracker_height": "TRACKER_HEIGHT",
}
_MAX_SCAN_BYTES = 2 * 1024 * 1024

_SLICE_RE = re.compile(
    r"\[\s*(\d+)\s*:\s*(\d+)\s*,\s*(\d+)\s*:\s*(\d+)\s*(?:,\s*:?\s*)?\]")
_RESIZE_RE = re.compile(
    r"resize\s*\([^,()]+,\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)")


# ---------------------------------------------------------------------------
# Auto-discovery of the real crop (no invented defaults)
# ---------------------------------------------------------------------------
def _search_dirs():
    dirs = []
    for d in (_HERE, os.getcwd()):
        d = os.path.abspath(d)
        if d not in dirs and os.path.isdir(d):
            dirs.append(d)
    return dirs


def _candidate_files(exts):
    seen = set()
    for d in _search_dirs():
        try:
            names = sorted(os.listdir(d))
        except OSError:
            continue
        for name in names:
            path = os.path.join(d, name)
            if path in seen or not os.path.isfile(path):
                continue
            if os.path.splitext(name)[1].lower() not in exts:
                continue
            if os.path.abspath(path) == os.path.abspath(__file__):
                continue
            try:
                if os.path.getsize(path) > _MAX_SCAN_BYTES:
                    continue
            except OSError:
                continue
            seen.add(path)
            yield path


def _crop_from_obj(obj):
    """Find a crop description anywhere inside a parsed JSON object."""
    if isinstance(obj, dict):
        if all(obj.get(k) is not None for k in _KEYS[:4]):
            return {k: float(obj[k]) for k in _KEYS if obj.get(k) is not None}
        crop = obj.get("crop")
        if isinstance(crop, (list, tuple)) and len(crop) == 4:
            out = dict(zip(_KEYS[:4], (float(v) for v in crop)))
        elif isinstance(crop, dict) and all(
                k in crop for k in ("x", "y", "width", "height")):
            out = {"crop_x": float(crop["x"]), "crop_y": float(crop["y"]),
                   "crop_width": float(crop["width"]),
                   "crop_height": float(crop["height"])}
        else:
            out = None
        if out is not None:
            for k in ("tracker_width", "tracker_height"):
                if obj.get(k) is not None:
                    out[k] = float(obj[k])
            return out
        for v in obj.values():
            found = _crop_from_obj(v)
            if found:
                return found
    elif isinstance(obj, list):
        for v in obj:
            found = _crop_from_obj(v)
            if found:
                return found
    return None


def _discover():
    """Return (config_or_None, list_of_candidate_descriptions)."""
    candidates = []

    for path in _candidate_files({".json"}):
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError):
            continue
        found = _crop_from_obj(data)
        if found:
            candidates.append((found, path))

    for path in _candidate_files({".py"}):
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                text = f.read()
        except OSError:
            continue
        slices = {tuple(int(g) for g in m.groups())
                  for m in _SLICE_RE.finditer(text)}
        resizes = {tuple(int(g) for g in m.groups())
                   for m in _RESIZE_RE.finditer(text)}
        for y0, y1, x0, x1 in slices:
            if y1 <= y0 or x1 <= x0:
                continue
            cfg = {"crop_x": float(x0), "crop_y": float(y0),
                   "crop_width": float(x1 - x0),
                   "crop_height": float(y1 - y0)}
            if len(resizes) == 1:
                w, h = next(iter(resizes))
                cfg["tracker_width"] = float(w)
                cfg["tracker_height"] = float(h)
            candidates.append((cfg, path))

    unique = {}
    for cfg, path in candidates:
        key = tuple(sorted(cfg.items()))
        unique.setdefault(key, (cfg, path))
    found = list(unique.values())
    if len(found) == 1:
        return found[0][0], found
    return None, found


# ---------------------------------------------------------------------------
# Configuration resolution
# ---------------------------------------------------------------------------
def _load_config():
    """Priority (lowest to highest): discovery, env vars, config file, CROP."""
    cfg = {k: None for k in _KEYS}
    discovered, candidates = _discover()
    if discovered:
        cfg.update(discovered)
    for k, env in _ENV.items():
        v = os.environ.get(env)
        if v not in (None, ""):
            cfg[k] = float(v)
    if os.path.isfile(_CONFIG_FILE):
        with open(_CONFIG_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        found = _crop_from_obj(data) or {}
        for k in _KEYS:
            if found.get(k) is not None:
                cfg[k] = float(found[k])
    if CROP:
        for k in _KEYS:
            if CROP.get(k) is not None:
                cfg[k] = float(CROP[k])
    return cfg, candidates


def _resolve(**overrides):
    cfg, candidates = _load_config()
    for k, v in overrides.items():
        if v is not None:
            cfg[k] = float(v)
    missing = [k for k in _KEYS[:4] if cfg[k] is None]
    if missing:
        if len(candidates) > 1:
            listing = "; ".join("%s from %s" % (c, p) for c, p in candidates)
            hint = " Several possible crops were found: %s." % listing
        else:
            hint = " No crop was found in %s." % ", ".join(_search_dirs())
        raise ValueError(
            "Tracker crop is not configured (missing: %s).%s Set CROP at the "
            "top of this file, pass the values as arguments, add them to %s, "
            "or set the TRACKER_* environment variables."
            % (", ".join(missing), hint, _CONFIG_FILE))
    if cfg["crop_width"] <= 0 or cfg["crop_height"] <= 0:
        raise ValueError("Crop width and height must be positive.")
    if cfg["tracker_width"] is None:
        cfg["tracker_width"] = cfg["crop_width"]
    if cfg["tracker_height"] is None:
        cfg["tracker_height"] = cfg["crop_height"]
    return cfg


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------
def to_tracker(x, y,
               crop_x=None, crop_y=None,
               crop_width=None, crop_height=None,
               tracker_width=None, tracker_height=None):
    """Convert an (x, y) pixel in the original video to tracker coordinates."""
    c = _resolve(crop_x=crop_x, crop_y=crop_y,
                 crop_width=crop_width, crop_height=crop_height,
                 tracker_width=tracker_width, tracker_height=tracker_height)

    sx = c["tracker_width"] / c["crop_width"]
    sy = c["tracker_height"] / c["crop_height"]
    tx = (float(x) - c["crop_x"]) * sx
    ty = (float(y) - c["crop_y"]) * sy

    if OUTPUT_MODE == "normalized":
        return (tx / c["tracker_width"], ty / c["tracker_height"])
    if OUTPUT_MODE == "centered":
        return (tx - c["tracker_width"] / 2.0, ty - c["tracker_height"] / 2.0)
    return (tx, ty)


def is_in_crop(x, y, crop_x=None, crop_y=None, crop_width=None,
               crop_height=None):
    """Return True if the original-video point (x, y) lies inside the crop."""
    c = _resolve(crop_x=crop_x, crop_y=crop_y,
                 crop_width=crop_width, crop_height=crop_height)
    return (c["crop_x"] <= x < c["crop_x"] + c["crop_width"] and
            c["crop_y"] <= y < c["crop_y"] + c["crop_height"])


if __name__ == "__main__":
    try:
        cfg = _resolve()
        print("using crop:", cfg)
        print("frame center ->", to_tracker(960, 540))
    except ValueError as e:
        print("Not configured yet:", e)
